Input: {"question": "Which educational institution did Yibing Maxine Tan attend?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "d1", "start": 0, "end": 58, "text": "Here is a potential Wikipedia entry for Yibing Maxine Tan:"}, "D1S2": {"document_number": 1, "doc_id": "d1", "start": 60, "end": 77, "text": "Yibing Maxine Tan"}, "D1S3": {"document_number": 1, "doc_id": "d1", "start": 79, "end": 224, "text": "Yibing Maxine Tan is a notable individual who holds a Master of Science degree in Aeronautics and Astronautics from the University of Washington."}, "D1S4": {"document_number": 1, "doc_id": "d1", "start": 225, "end": 234, "text": "Education"}, "D1S5": {"document_number": 1, "doc_id": "d1", "start": 236, "end": 418, "text": "Tan earned her Master of Science degree in Aeronautics and Astronautics from the University of Washington, a public research university located in Seattle, Washington, United States."}, "D1S6": {"document_number": 1, "doc_id": "d1", "start": 419, "end": 422, "text": "[1]"}, "D1S7": {"document_number": 1, "doc_id": "d1", "start": 424, "end": 448, "text": "University of Washington"}, "D1S8": {"document_number": 1, "doc_id": "d1", "start": 450, "end": 527, "text": "The University of Washington is a public research university founded in 1861."}, "D1S9": {"document_number": 1, "doc_id": "d1", "start": 528, "end": 634, "text": "It is located in Seattle, Washington, and is known for its academic excellence and research opportunities."}, "D1S10": {"document_number": 1, "doc_id": "d1", "start": 635, "end": 783, "text": "[2] The university offers a wide range of undergraduate and graduate degree programs, including a Master of Science in Aeronautics and Astronautics."}, "D1S11": {"document_number": 1, "doc_id": "d1", "start": 784, "end": 787, "text": "[3]"}, "D1S12": {"document_number": 1, "doc_id": "d1", "start": 789, "end": 799, "text": "References"}, "D1S13": {"document_number": 1, "doc_id": "d1", "start": 801, "end": 830, "text": "[1]